Q: Cycles in small directed graph A: <p>You can just follow the path starting from a node, and mark each node you visit like that as visited. When you encounter a visited node, you have a cycle. Then do the same for the next unvisited node until all are visited.</p>
<p>The data structure for representing such a graph could be an array, where the index (0, 1, ..., 4) identifies the node, and the value at that index identifies the neighbor to which the directed edge from that node goes.</p>
<p>Here is a simple implementation in JavaScript:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function collectCycles(graph) {
    const cycles = [];
    const visited = Array(graph.length).fill(false);
    for (let node = 0; node &lt; graph.length; node++) {
        const cycle = [];
        while (!visited[node]) {
            visited[node] = true;
            cycle.push(node);
            node = graph[node]; // go to (only) neighbor
        }
        if (cycle.length &gt; 0) cycles.push(cycle);
    }
    return cycles;
}

// Example
const graph = [4, 2, 1, 3, 0];
for (const cycle of collectCycles(graph)) {
    console.log("cycle", ...cycle);
}</code></pre>
